package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math.util.MathUtils.factorial
 */
public class MathUtils_factorial_TriageGen0Test {

    @Test
    public void testFactorialWithValidSmallN() {
        // Testing valid inputs within the range [1, 20]
        // Note: Based on the code, if n < 1 it throws exception. 
        // Usually factorial(0) is 1, but this specific implementation throws IllegalArgumentException for n < 1.
        assertEquals(1L, MathUtils.factorial(1));
        assertEquals(2L, MathUtils.factorial(2));
        assertEquals(6L, MathUtils.factorial(3));
        assertEquals(120L, MathUtils.factorial(5));
        assertEquals(3628800L, MathUtils.factorial(10));
    }










}

